package com.volna.inventory_service.entity;
import com.volna.inventory_service.enums.InventoryStatus;import jakarta.persistence.*;import java.math.BigDecimal;import java.time.*;import java.util.UUID;
@Entity @Table(name="inventory_items") public class InventoryItem {
 @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(name="restaurant_id",nullable=false) private UUID restaurantId; @Column(nullable=false) private String name; @Column(nullable=false) private String sku; private String category; private String unit; @Column(name="stock_level",nullable=false,precision=12,scale=2) private BigDecimal stockLevel=BigDecimal.ZERO; @Column(name="minimum_stock",nullable=false,precision=12,scale=2) private BigDecimal minimumStock=BigDecimal.ZERO; @Column(name="unit_cost",nullable=false,precision=12,scale=2) private BigDecimal unitCost=BigDecimal.ZERO; @Column(name="expiry_date") private LocalDate expiryDate; @Enumerated(EnumType.STRING) @Column(nullable=false,length=30) private InventoryStatus status; private String supplier; @Column(name="created_at",nullable=false) private LocalDateTime createdAt; @Column(name="updated_at",nullable=false) private LocalDateTime updatedAt;
 @PrePersist void create(){createdAt=LocalDateTime.now();updatedAt=createdAt;refreshStatus();}@PreUpdate void update(){updatedAt=LocalDateTime.now();refreshStatus();} void refreshStatus(){if(stockLevel==null)stockLevel=BigDecimal.ZERO;if(minimumStock==null)minimumStock=BigDecimal.ZERO;status=stockLevel.compareTo(BigDecimal.ZERO)<=0?InventoryStatus.OUT_OF_STOCK:stockLevel.compareTo(minimumStock)<=0?InventoryStatus.LOW_STOCK:InventoryStatus.IN_STOCK;}
 public Long getId(){return id;} public UUID getRestaurantId(){return restaurantId;}public void setRestaurantId(UUID v){restaurantId=v;}public String getName(){return name;}public void setName(String v){name=v;}public String getSku(){return sku;}public void setSku(String v){sku=v;}public String getCategory(){return category;}public void setCategory(String v){category=v;}public String getUnit(){return unit;}public void setUnit(String v){unit=v;}public BigDecimal getStockLevel(){return stockLevel;}public void setStockLevel(BigDecimal v){stockLevel=v;}public BigDecimal getMinimumStock(){return minimumStock;}public void setMinimumStock(BigDecimal v){minimumStock=v;}public BigDecimal getUnitCost(){return unitCost;}public void setUnitCost(BigDecimal v){unitCost=v;}public LocalDate getExpiryDate(){return expiryDate;}public void setExpiryDate(LocalDate v){expiryDate=v;}public InventoryStatus getStatus(){return status;}public String getSupplier(){return supplier;}public void setSupplier(String v){supplier=v;} }
